import{_ as t,o as i,c as a,a3 as s}from"./chunks/framework.DH7DibUz.js";const h=JSON.parse('{"title":"SGC general assembly 2023","description":"","frontmatter":{"title":"SGC general assembly 2023","date":"2023-11-16T00:00:00.000Z","author":"Ludovic Räss, Marj Tonini","tags":["General Assembly","Event"]},"headers":[],"relativePath":"events/sgc-general-assembly-23.md","filePath":"events/sgc-general-assembly-23.md","lastUpdated":1794345340000}'),o={name:"events/sgc-general-assembly-23.md"};function n(r,e,l,c,d,m){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="sgc-general-assembly-2023" tabindex="-1">SGC general assembly 2023 <a class="header-anchor" href="#sgc-general-assembly-2023" aria-label="Permalink to &quot;SGC general assembly 2023&quot;">​</a></h1><p>On Thursday 16 November will be held the general assembly of the Swiss Geocomputing Centre.</p><h2 id="items-to-discuss" tabindex="-1">Items to discuss <a class="header-anchor" href="#items-to-discuss" aria-label="Permalink to &quot;Items to discuss&quot;">​</a></h2><p>We will discuss the following items:</p><ol><li><p><strong>Coffee meetings</strong> - Organization of regular coffee meetings (once to twice a month) mainly addressed to PhD and Postdoc of our Faculty, about main topics in the domain of geocomputing (e.g., Open science and reproducibility - FAIR Principles; GitHub - version control and collaborative development; comparison of different program languages - R vs Python vs Julia).</p></li><li><p><strong>Budget</strong> – Settle a yearly budget, ideally financed by the Institutes or the Faculty (via FINV), to support the activities of the Centre, such as seminars (possibility of inviting external speakers), workshops, infrastructures.</p></li><li><p><strong>SGC event</strong> – Organization of a one- or two-day main event (seminars and workshops) to promote the activities related to the Centre.</p></li><li><p><strong>SGC direction</strong> - The Director&#39;s term of office is 2 years, renewable for 3 consecutive terms. I propose the renewal of my mandate, and to add Ludovic (in addition to Christian) as vice-directors. These proposals must be approved by the Scientific Committee (SC).</p></li><li><p><strong>SGC reorganization</strong> - According to the « Guidelines », any member of the Faculty can ask to be affiliated to the Centre, while the SC has a more active role in the management of the Centre. I propose to invite more researchers to be affiliated and, for you, to confirm if you wish remaining a member of the SC or to change your position as affiliated member.</p></li></ol><hr><h2 id="meeting-summary" tabindex="-1">Meeting summary <a class="header-anchor" href="#meeting-summary" aria-label="Permalink to &quot;Meeting summary&quot;">​</a></h2><h3 id="attendees" tabindex="-1">Attendees <a class="header-anchor" href="#attendees" aria-label="Permalink to &quot;Attendees&quot;">​</a></h3><p><em>Present:</em> Guillaume Jouvet, Tom Beucler, Beatriz Quintal, György Hetény, Stefan Schmalholz, Romain Pilon, Grégoire Mariéthoz, Céline Rosenblat, Christian Kaiser, Marj Tonini, Ludovic Räss</p><p><em>Absent:</em> -</p><h3 id="agenda" tabindex="-1">Agenda <a class="header-anchor" href="#agenda" aria-label="Permalink to &quot;Agenda&quot;">​</a></h3><ol><li><p>Coffee meeting propositions</p><ul><li>Open science (repos, publications, reproducible workflows)</li><li>FAIR principles</li><li>Geodata handling</li><li>Present about UN-GGM activities (Céline): <ul><li>Common geodata platform: GEO AI, geology, remote sensing</li><li>Make SGC visible there?</li><li>See if one could position SGC within expert groups in such target entities</li></ul></li><li>Each interested FGSE research group presents methods and challenges respective to their research</li><li>Include MSc student as well in the meetings (promote it for them as well)</li><li>Possibly enable finding synergies between MSc students and research groups</li><li><strong>TODO</strong>: Settle a series of seminar alternating between FGSE research groups in Jan – Feb 24</li></ul></li><li><p>Budget</p><ul><li>FINV24 b to acquire some annual budget for the centre</li><li>See if institutes could take over some financing in a later stage</li><li>Check out as international relations Unil may help financing Summer schools</li><li><strong>TODO</strong>: draft a 2024 budget and ask institutes</li></ul></li><li><p>Events</p><ul><li>Plan 1 or 2 larger events for 2024 (workshop)</li></ul></li><li><p>Elections</p><ul><li>The assembly re-elected Marj Tonini as SGC director for a second term</li><li>The assembly re-elected Christian Kaiser as SGC co-director for a second term</li><li>The assembly elected Ludovic Räss as SGC co-director</li></ul></li><li><p>SGC reorgainsation</p><ul><li>All members accepted the proposed re-organisation of the SGC</li></ul></li></ol>',12)])])}const g=t(o,[["render",n]]);export{h as __pageData,g as default};
